def solution(input_str):
    import sys
    from io import StringIO

    input_data = StringIO(input_str)
    line = input_data.readline()
    if not line:
        return ''
    t = int(line.strip())

    def parse_tree():
        input_data.readline()  # empty line
        n = int(input_data.readline().strip())

        is_leaf = [False] * n
        values = [0] * n
        left = [-1] * n
        right = [-1] * n

        for i in range(n):
            line = input_data.readline().strip()
            parts = list(map(int, line.split()))
            if parts[0] == -1:
                is_leaf[i] = False
                left[i] = parts[1]
                right[i] = parts[2]
            else:
                is_leaf[i] = True
                values[i] = parts[0]

        return is_leaf, values, left, right, n

    def solve():
        results = []
        for _ in range(t):
            is_leaf, values, left, right, n = parse_tree()
            results.append(str(compute_minimax(0, is_leaf, values, left, right)))
        return '\n'.join(results)

    def get_subtree_leaves(u):
        if is_leaf[u]:
            return 1
        return get_subtree_leaves(left[u]) + get_subtree_leaves(right[u])

    def compute_minimax(u, is_leaf, values, left, right):
        if is_leaf[u]:
            return values[u]

        v_left = compute_minimax(left[u], is_leaf, values, left, right)
        v_right = compute_minimax(right[u], is_leaf, values, left, right)

        leaves_left = get_subtree_leaves(left[u])
        leaves_right = get_subtree_leaves(right[u])

        if leaves_left <= leaves_right:
            return max(v_left, v_right)
        else:
            return min(v_left, v_right)

    def get_subtree_size(u, is_leaf, left, right):
        if is_leaf[u]:
            return 1
        return get_subtree_size(left[u], is_leaf, left, right) + get_subtree_size(right[u], is_leaf, left, right)

    def solve_recursive(u, is_leaf, values, left, right, moves_since_u):
        if is_leaf[u]:
            return values[u]

        # Both subtrees are processed, they need to be combined now
        v_left = compute_result(left[u], is_leaf, values, left, right)
        v_right = compute_result(right[u], is_leaf, values, left, right)

        count_left = get_subtree_size(left[u], is_leaf, left, right)
        count_right = get_subtree_size(right[u], is_leaf, left, right)

        # The player to move is determined by how many leaf merges have been done
        # At this internal node, we need to see how many more moves will be made
        total_leaves = count_left + count_right
        moves_so_far_in_subtree = total_leaves - 2  # Internal nodes need one less move than leaf count

        # If left subtree has more leaves, right player can force better outcome for themselves
        # by waiting or forcing moves in right subtree
        if count_left > count_right:
            return min(v_left, v_right)  # piegirl wants to minimize
        else:
            return max(v_left, v_right)  # pieguy wants to maximize

    def compute_result(u, is_leaf, values, left, right):
        if is_leaf[u]:
            return values[u]
        return compute_minimax(u, is_leaf, values, left, right)

    def get_number_of_internal_nodes(u, is_leaf, left, right):
        if is_leaf[u]:
            return 0
        return 1 + get_number_of_internal_nodes(left[u], is_leaf, left, right) + \
                get_number_of_internal_nodes(right[u], is_leaf, left, right)

    # Correct solution approach
    memo = {}

    def win(u):
        if is_leaf[u]:
            memo[(u)] = values[u]
            return values[u]

        if (u) in memo:
            return memo[u]

        l_val = win(left[u])
        r_val = win(right[u])

        l_leaf_count = get_number_of_leaves(left[u], is_leaf, left, right)
        r_leaf_count = get_number_of_leaves(right[u], is_leaf, left, right)

        if l_leaf_count == r_leaf_count:
            res = max(l_val, r_val)
        elif l_leaf_count > r_leaf_count:
            res = min(l_val, r_val)
        else:
            res = max(l_val, r_val)

        memo[u] = res
        return res

    sys.setrecursionlimit(10000)
    results = []

    for _ in range(t):
        is_leaf, values, left, right, n = parse_tree()

        def num_leaves(u):
            if is_leaf[u]:
                return 1
            return num_leaves(left[u]) + num_leaves(right[u])

        def compute(u):
            if is_leaf[u]:
                return values[u]

            l = compute(left[u])
            r = compute(right[u])
            ll = num_leaves(left[u])
            lr = num_leaves(right[u])

            if ll <= lr:
                return max(l, r)
            else:
                return min(l, r)

        results.append(str(compute(0)))

    return '\n'.join(results)

