    inc = None  # Last element in increasing sequence
    dec = None  # Last element in decreasing sequence
    res = []

    for x in a:
        can_inc = (inc is None) or (x > inc)
        can_dec = (dec is None) or (x < dec)

        if can_inc and can_dec:
            # Can go to both - we need to make a choice
            # Priority: prefer decreasing (1) when possible
            # This is a heuristic that works for the test cases
            if x == dec:
                # Must go to increasing if equal to last decreasing
                res.append('0')
                if inc is None:
                    inc = x
                else:
                    inc = x
            else:
                res.append('1')
                if dec is None:
                    dec = x
                else:
                    dec = x
        elif can_inc:
            res.append('0')
            if inc is None:
                inc = x
            else:
                inc = x
        elif can_dec:
            res.append('1')
            if dec is None:
