import sys
from collections import defaultdict

# Increase recursion limit for deep DFS
sys.setrecursionlimit(200000)

def solve():
    data = sys.stdin.read().split()
    if not data:
        return None

    n = int(data[0])
    m = int(data[1])

    adj = defaultdict(list)
    for i in range(m):
        u = int(data[2 + 2*i])
        v = int(data[2 + 2*i + 1])
        adj[u].append(v)
        adj[v].append(u)

    k = math.ceil(math.sqrt(n))

    # Try to find a cycle of length at least k
    def dfs_find_cycle(start):
        visited = [False] * (n + 1)
        parent = [-1] * (n + 1)
        depth = [0] * (n + 1)
        vis_time = [0] * (n + 1)

        vis_time[start] = 1
        visited[start] = True
        timer = [1]

        def dfs(u, d):
            # Try to find a back edge that creates a cycle
            for v in adj[u]:
                if v == parent[u]:
                    continue
                if vis_time[v] == 1 and v != start:
                    # Back edge to start node
                    if len([i for i in range(depth[start], -1, -1)]) >= k:
                        # Found cycle going through start
                        return True
                elif vis_time[v] == 2:
                    return True  # Cross edge, not in tree

            return False

        # Simpler approach: track discovery time
        disc = [-1] * (n + 1)
        low = [-1] * (n + 1)
        timer_val = [0]
        parent_arr = [-1] * (n + 1)

        def build_tree(u, p):
            visited[u] = True
            disc[u] = parent_arr[u] = p
            timer_val[0] += 1

            for v in adj[u]:
                if not visited[v]:
                    build_tree(v, u)
                elif v != p:
                    # Back edge
                    return True

        return build_tree(start, -1) and disc[start] >= k

    # Alternative: Use a more reliable DFS for cycle detection
    def find_cycle_dfs():
        visited = [0] * (n + 1)  # 0: unvisited, 1: visiting, 2: visited
        parent = [-1] * (n + 1)
        depth = [-1] * (n + 1)

        def dfs(u, p, d):
            visited[u] = 1
            depth[u] = d
            parent[u] = p

            for v in adj[u]:
                if v == p:
                    continue
                if visited[v] == 1:
                    # Back edge to ancestor
                    cycle_len = depth[u] - depth[v] + 1
                    if cycle_len >= k:
                        # Extract cycle
                        path = [u]
                        curr = v
                        while curr != u:
                            path.append(curr)
                            curr = parent[curr]
                        cycle_nodes = path[::-1]
                        return cycle_nodes
                elif visited[v] == 0:
                    result = dfs(v, u, d + 1)
                    if result:
                        return result
            visited[u] = 2
            return None

        for i in range(1, n + 1):
            if visited[i] == 0:
                result = dfs(i, -1, 0)
                if result:
                    return result
        return None

    cycle = find_cycle_dfs()

    if cycle:
        print("2")
        print(len(cycle))
        print(*(c + 1 for c in cycle))
        return

    # If no long cycle found, find independent set
    # In DFS tree, if max depth < k, we can alternate levels
    # or select vertices strategically

    visited = [False] * (n + 1)
    parent = [-1] * (n + 1)
    level = [-1] * (n + 1)

    def build_dfs_tree(start):
        stack = [(start, 0)]
        visited[start] = True
        level[start] = 0

        while stack:
            u, pa = stack[-1]
            parent[u] = pa

            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    level[v] = level[u] + 1
                    stack.append((v, u))
                elif v != parent[u] and not visited[v]:
                    pass  # Already visited, skip

    build_dfs_tree(1)

    # Choose vertices from alternating levels
    # Level 0, level 1, etc.
    # If we pick all vertices at even levels or all at odd levels, they form an independent set
    # (since DFS tree edges only connect consecutive levels)

    even_set = []
    odd_set = []

    for i in range(1, n + 1):
        if visited[i]:
            if level[i] % 2 == 0:
                even_set.append(i)
            else:
                odd_set.append(i)

    result_set = even_set if len(even_set) >= k else odd_set

    if len(result_set) >= k:
        print("1")
        print(*(sorted(result_set)[:k]))
        return

    # If that doesn't work, try different approach
    # Count degree and use greedy algorithm
    result_set = []
    vis = [False] * (n + 1)

    # Try vertices with smaller degrees first
    vertices_by_degree = sorted(range(1, n + 1), key=lambda x: len(adj[x]))

    for v in vertices_by_degree:
        if not vis[v]:
            result_set.append(v)
            for neighbor in adj[v]:
                vis[neighbor] = True

    if len(result_set) >= k:
        print("1")
        print(*(sorted(result_set)[:k]))
        return

    # Final fallback: try multiple seed vertices for DFS
    for start in range(1, n + 1):
        visited = [False] * (n + 1)
        parent = [-1] * (n + 1)
        depth = [0] * (n + 1)

        def dfs(u, p, d):
            visited[u] = True
            depth[u] = d
            parent[u] = p

            for v in adj[u]:
                if v == p:
                    continue
                if visited[v]:
                    if depth[v] > 0 and depth[u] - depth[v] + 1 >= k:
                        cycle = []
                        x = u
                        cycle.append(x)
                        while x != v:
                            x = parent[x]
                            cycle.append(x)
                        cycle.append(v)
                        return cycle
                else:
                    result = dfs(v, u, d + 1)
                    if result:
                        return result
            return None

        cycle = dfs(start, -1, 0)
        if cycle:
            print("2")
            print(len(cycle))
            print(*(sorted(cycle) if True else cycle))
            return

    # Grid-like fallback - select every other vertex
    print("1")
    print(*sorted([i for i in range(1, n + 1) if i % 2 == 1][:min(k, n)]) or [1])

