def solve_custom(n, m, edges):
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    k = math.ceil(math.sqrt(n))

    # Try to find cycle using DFS with path tracking
    def find_long_cycle():
        disc = {}
        parent = {}
        path = []
        visited = {}
        timer = [0]

        def dfs(u):
            disc[u] = timer[0]
            timer[0] += 1
            visited[u] = True
            path.append(u)

            for v in sorted(adj[u], reverse=True):
                if v not in visited:
                    parent[v] = u
                    result = dfs(v)
                    if result:
                        return result
                elif v in disc:
                    # Back edge found
                    if parent[u] is not None:
                        # Try to form cycle
                        path_len = len(path)
                        if path_len >= k:
                            return list(reversed(path))[:k]
                    if disc[v] < disc[u] and disc[u] - disc[v] + 1 >= k:
                        idx = disc[v] if disc[v] in disc else len(path) - 1
                        if disc[v] in disc:
                            cycle_len = disc[u] - disc[v] + 1
                            if cycle_len >= k:
                                # Build cycle
                                start_node = None
                                for i, node in enumerate(path):
                                    if node == v:
                                        start_node = i
                                        break
                                if start_node is not None:
                                    return path[start_node:]

            visited[u] = False
            path.pop()
            return None

        for start in range(1, n + 1):
            result = dfs(start)
            if result:
                return result
        return None

    cycle = find_long_cycle()

    if cycle:
        output = "2\n" + str(len(cycle)) + "\n" + " ".join(map(str, cycle)) + "\n"
        return output

    # No long cycle - find independent set
    visited = set()
    indep_set = []
    vis = [False] * (n + 1)

    # Greedy independent set by degree
    nodes_by_degree = sorted(range(1, n + 1), key=lambda x: len(adj[x]))

    for v in nodes_by_degree:
        if vis[v]:
            continue
        indep_set.append(v)
        for neighbor in adj[v]:
            vis[neighbor] = True

    if len(indep_set) >= k:
        return "1\n" + " ".join(map(str, sorted(indep_set)[:k])) + "\n"

    # Try level-based independent set
    visited = [False] * (n + 1)
    level = {}

    def dfs_level(u, start, p, d):
        visited[u] = True
        level[u] = d

        for v in adj[u]:
            if not visited[v]:
                dfs_level(v, start, u, d + 1)

    dfs_level(1, 1, -1, 0)

    even_nodes = [i for i in range(1, n + 1) if visited[i] and level[i] % 2 == 0]
    odd_nodes = [i for i in range(1, n + 1) if visited[i] and level[i] % 2 == 1]

    result = even_nodes if len(even_nodes) >= k else odd_nodes

    if result:
        return "1\n" + " ".join(map(str, sorted(result)[:k])) + "\n"

    # Fallback: simple set
    result = [i for i in range(1, n + 1) if i % 2 == 0][1:][len([i for i in range(1, n + 1) if i % 2 == 0]) % k:]

    return "1\n" + " ".join(map(str, sorted([i for i in range(1, n + 1) if i % 2 == 1][:k)]))

