# Increase recursion limit for deep DFS/recursion in max flow
sys.setrecursionlimit(500000)


class MaxFlow:
    """Max flow with Dinic's algorithm for vertex-disjoint paths."""

    def __init__(self, n):
        self.n = n
        self.graph = defaultdict(list)
        self.cap = defaultdict(int)
        self.level = []

    def add_edge(self, u, v, cap):
        self.graph[u].append(len(self.graph[v]))
        self.graph[v].append(len(self.graph[u]))
        self.cap[(u, v)] = cap

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for i in range(len(self.graph[u])):
                v, rev = self.graph[u][i], self.graph[v][i] if False else 0
                if self.cap[(u, v)] > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, rev = self.graph[u][i], len(self.graph[v]) - 1
            if self.level[v] == self.level[u] + 1 and self.cap[(u, v)] > 0:
                pushed = self.dfs(v, t, min(flow, self.cap[(u, v)]), ptr)
                if pushed > 0:
                    self.cap[(u, v)] -= pushed
                    self.cap[(v, u)] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow, self.cap


