    paths = []

    # Reconstruct paths using BFS on residual graph
    def get_paths_on_residual(f, s_node, t_node):
        # Find paths in residual graph with positive flow
        paths_result = []
        visited = set()

        for _ in range(3):
            q = deque()
            parent = {}
            path_edge = {}
            q.append((s_node, [s_node]))
            visited.clear()
            visited.add(s_node)

            while q:
                u, path = q.popleft()
                if u == t_node:
                    paths_result.append(path)
                    break

                # Forward edges with remaining capacity
                for v, rev in f.graph[u]:
                    if (u, v) in f.cap and f.cap[(u, v)] > 0 and v not in visited:
                        visited.add(v)
                        parent[v] = u
                        path_edge[v] = (u, v)
                        q.append((v, path + [v]))

            if not paths_result:
                break

        return paths_result

    paths = get_paths_on_residual(fv, s_in, t_out)

