        lines.append(f"{len(p)} {paths_str}")

    return "YES\n" + '\n'.join(lines) + '\n'


def reconstruct_path(fv, s, t):
    # Simple path reconstruction
    path = [s]
    current = s
    visited = {s}

    while current != t and current is not None:
        found = False
        for neighbor in sorted(fv.graph[current]):
            if (current, neighbor) in fv.cap and fv.cap[(current, neighbor)] > 0:
                if neighbor == t:
                    path.append(neighbor)
                    return path
                elif neighbor not in visited:
                    visited.add(neighbor)
                    path.append(neighbor)
                    current = neighbor
                    found = True
                    break
        if not found:
            current = None
            break

    if current == t:
        return path
    return None


