from collections import Counter
from itertools import product, set

def solution(input_text):
    lines = input_text.strip().split('\n')
    n, m = map(int, lines[0].split())
    matrix = [list(line) for line in lines[1:n+1]]

    def get_palindrome_arrangements(row_chars):
        """Get all unique string arrangements that form palindromes."""
        freq = Counter(row_chars)

        # Check if can form palindrome (at most one char with odd count)
        odd_count = sum(c % 2 for c in freq.values())
        if odd_count > 1:
            return []

        results = set()
        if not row_chars:
            return [""]

        # Build first half
        half = []
        for ch, count in freq.items():
            half.extend([ch] * (count // 2))

        # Generate all permutations of first half
        half_set = set()
        def permute_half(arr, idx, p):  # Use set to avoid duplicates
            if idx == len(arr):
                half_set.add(''.join(p))
                return
            for i in range(idx, len(arr)):
                p[idx], p[i] = p[i], p[idx]
                permute_half(arr, idx + 1, p)
                p[idx], p[i] = p[i], p[idx]

        arr = list(half)
        permute_half(arr, 0, [])

        # Combine with middle (if odd length) and reverse
        for first in half_set:
            if len(row_chars) % 2 == 1:
                odd_char = [ch for ch, count in freq.items() if count % 2 == 1][0]
                second = first + odd_char + first[::-1]
                results.add(second)
            else:
                results.add(first + first[::-1])

        return list(results)

    def is_columns_palindromic(matrix):
        """Check if all columns are palindromes."""
        if not matrix or not matrix[0]:
            return True

        for c in range(len(matrix[0])):
            col = ''.join(matrix[r][c] for r in range(len(matrix)))
            if col != col[::-1]:
                return False
        return True

    ans = 0

    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    # Extract submatrix
                    sub = [[matrix[i][j] for j in range(c1, c2+1)] for i in range(r1, r2+1)]

                    # Get all palindrome arrangements for each row
                    row_perms = []
                    all_valid = True

                    for row in sub:
                        perms = get_palindrome_arrangements(row)
                        if not perms:
                            all_valid = False
                            break
                        row_perms.append(perms)

                    if all_valid:
                        # Try all combinations
                        found = False
                        for combo in product(*row_perms):
                            if is_columns_palindromic(list(combo)):
                                found = True
                                break
                        if found:
                            ans += 1

    return str(ans)


