def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    N, M, K = int(parts[0]), int(parts[1]), int(parts[2])

    transformers = []
    for i in range(1, 1 + K):
        x, y, d, t, e = [int(p) for p in lines[i].split()]
        transformers.append((x, y, d, t, e))

    # Calculate which transformers are at each position (r, c) at time t
    # transformer_cost[r][c] = sum of energy of all transformers at (r,c) when Blackout arrives
    # Time to reach (r,c) is exactly r+c in any path using only right/down moves
    transformer_cost = {}

    for (x, y, d, t_start, e) in transformers:
        # Transformer is active for all t >= t_start
        # It cycles through 4 positions every 4 time units
        if t_start > N + M - 2:
            # Never reachable within grid constraints
            continue

        for r in range(N):
            for c in range(M):
                t = r + c
                if t >= t_start:
                    rel = (t - t_start) % 4
                    if rel == 0:
                        tr, tc = x, y
                    elif rel == 1:
                        tr, tc = x + d, y - d
                    elif rel == 2:
                        tr, tc = x + d, y
                    elif rel == 3:
                        tr, tc = x, y + d

                    if tr == r and tc == c:
                        if (r, c) not in transformer_cost:
                            transformer_cost[(r, c)] = 0
                        transformer_cost[(r, c)] += e

    # DP: dp[r][c] = minimum energy to reach (r, c)
    dp = [[float('inf')] * M for _ in range(N)]

    for r in range(N):
        for c in range(M):
            # Cost of any transformer at (r, c) when Blackout arrives here at time r+c
            cost = transformer_cost.get((r, c), 0)

            if r == 0 and c == 0:
                dp[r][c] = cost
            else:
                dp[r][c] = float('inf')
                # Can arrive from top (r-1, c)
                if r > 0:
                    dp[r][c] = min(dp[r][c], dp[r-1][c])
                # Can arrive from left (r, c-1)
                if c > 0:
                    dp[r][c] = min(dp[r][c], dp[r][c-1])
                dp[r][c] += cost

    return str(dp[N-1][M-1]) + '\n'

import math

def get_divisors(n):
    """Get all divisors of n greater than 1"""
    divs = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i += 1
    return sorted([d for d in divs if d > 1], reverse=True)

