    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    parts = lines[0].split()
    n = int(parts[0])
    t = int(parts[1])

    queries = []
    for i in range(1, t + 1):
        coords = lines[i].split()
        queries.append((int(coords[0]), int(coords[1])))

    if n == 0:
        return '\n'.join('0' for _ in range(t))

    from collections import defaultdict, deque

    # Simulate the spreading process
    # Using BFS with early termination when stable

    ants = defaultdict(int)
    ants[(0, 0)] = n

    final = defaultdict(int)
    processed = set()
    queue = deque([(0, 0)])

    # Estimate maximum spread - bounded by n/2 in Manhattan distance
    # A safer bound: use the number of groups of 4
    group_count = n // 4 + 1

    # Process in layers (by Manhattan distance)
    max_layers = group_count + 2

    for layer in range(max_layers):
        current_positions = set()
        next_positions = set()

        # Find unprocessed positions at this layer
        if processed:
            pos_list = list(ants.keys())
            for pos in pos_list:
                if (pos[0] + pos[1]) > 0 and pos not in processed:
                    if abs(pos[0]) + abs(pos[1]) == layer:
                        current_positions.add(pos)
                    elif abs(pos[0]) + abs(pos[1]) == layer + 1 and pos not in processed and pos not in next_positions:
                        next_positions.add(pos)

        if not current_positions:
            break

        # Check remaining ants while processing in groups of 4
        for pos in list(ants.keys()):
            if pos not in processed and ants[pos] > 0:
                cnt = ants[pos]
                if cnt >= 4:
                    ants[pos] -= 4
                    # 4 ants scatter to 4 neighbors
                    for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                        npos = (pos[0] + dx, pos[1] + dy)
                        ants[npos] += 1
                    current_positions.add(pos)

        # Process remaining ants that couldn't move
        for pos in list(final.keys()):
            if pos not in processed and ants.get(pos, 0) > 0:
                if ants[pos] < 4:
                    final[pos] += ants[pos]
                    ants[pos] = 0

        # Termination check
        can_move = False
        for pos in ants:
            if pos not in processed and ants[pos] >= 4:
                can_move = True
                break
        processed.update(current_positions)

        if not can_move:
            break

    # Final pass: add remaining counters
    for pos in ants:
        if ants[pos] > 0:
            final[pos] += ants[pos]

    # Answer queries
    results = []
    for x, y in queries:
        results.append(str(final.get((x, y), 0)))

    return '\n'.join(results)

