def solution(input_str: str) -> str:
    n, k, l = map(int, input_str.strip().split())
    MOD = 998244353

    # Precompute factorials and their modular inverses
    fact = [1] * (n + 1)
    inv = [1] * (n + 1)

    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % MOD

    def nCr(n_val, r_val):
        if r_val < 0 or r_val > n_val:
            return 0
        return fact[n_val] * inv[r_val] % MOD * inv[n_val - r_val] % MOD

    answer = 0

    for j in range(k, n + 1):
        inner_sum = 0
        for m in range(0, j):
            sign = 1 if m % 2 == 0 else -1
            inv_2m1 = pow(2 * m + 1, MOD - 2, MOD)
            inner_sum = (inner_sum + sign * nCr(j, m) * inv_2m1) % MOD

        contribution = nCr(n, j) * inner_sum
        answer = (answer + contribution) % MOD

    answer = answer * (l % MOD) % MOD

    return str(answer)

