def is_valid_axis_square(matrix, n, m, r, c, size):
    """Check if there's an axis-aligned square of given size at (r,c)"""
    border_cells = set()

    # Top and bottom rows of the square
    for i in range(c, c + size):
        border_cells.add((r, i))
        border_cells.add((r + size - 1, i))

    # Left and right columns of the square
    for i in range(r, r + size):
        border_cells.add((i, c))
        border_cells.add((i, c + size - 1))

    # Check all border cells are 1s
    for r_cell, c_cell in border_cells:
        if matrix[r_cell][c_cell] != 1:
            return False

    # Check no non-border 1s touch any border cell
    for r_cell, c_cell in border_cells:
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = r_cell + dr, c_cell + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1 and (nr, nc) not in border_cells:
                        return False

    return True


def is_valid_diagonal_square(matrix, n, m, center_r, center_c, size):
    """Check if there's a diagonal square with center at (center_r, center_c) and radius size"""
    border_cells = set()

    # Border cells: all cells with Manhattan distance == size from center
    for i in range(center_r - size, center_r + size + 1):
        for j in range(center_c - size, center_c + size + 1):
            if abs(i - center_r) + abs(j - center_c) == size:
