class FenwickTree:
    def __init__(self, size):
        self.tree = [0] * (size + 1)

    def update(self, idx, delta):
        idx += 1
        while idx < len(self.tree):
            self.tree[idx] += delta
            idx += idx & (-idx)

    def query(self, idx):
        idx += 1
        total = 0
        while idx > 0:
            total += self.tree[idx]
            idx -= idx & (-idx)
        return total

    def query_range(self, l, r):
        if l > r:
            return 0
        return self.query(r) - self.query(l - 1)

