                new_len = 0
                for lp, pl in ap_lengths:
                    if pl > new_len:
                        new_len = pl

                if orig_len > 0 and orig_len > new_len:
                    improvement += m
                elif len(p) > orig_len:
                    improvement += m * len(p) - m * orig_len if orig_len > 0 else m * len(p)

            # Track improvement properly
            if improvement > best_improvement:
                best_improvement = improvement
                best_prefix = p
                best_idx = i

        if best_prefix is not None and best_idx != -1:
            remaining.pop(best_idx)
            assigned.append(best_prefix)

    # Calculate final cost
    total_cost = 0
