def solve_match(a, b):
    """
    Try to find the best match score for Team A given total points (a, b)
    Best = most sets won by Team A, then maximize x - y
    """

    # List of possible match scores in order of preference for Team A
    # Format: (sets_won_A, sets_won_B)
    match_scores = [
