def find_valid_sets(total_a, total_b, wa, wb, total_sets, 
                     current_set_a, solutions, path):
    """
    Find valid set assignments using DFS/backtracking
    current_set_a: sum of points so far
    solutions: accumulated solution (list of sets)
    path: current path being explored
    """

    # If we've filled all sets
    if len(path) == total_sets:
        # Check if totals match
        if sum(p[0] for p in path) == total_a:
            # We need to check the sum of b
            return solutions

        return None

    # If teams already have enough points, need remaining sum to match
    if current_set_a >= total_a:
        return None

    # Remaining sets needed
    remaining = total_sets - len(path)
    remaining_a = total_a - current_set_a
    remaining_b = total_b - sum(p[1] for p in path)

    # Pruning: if remaining points can't possibly fit in remaining sets
    if remaining_a < 0 or remaining_b < 0:
        return None

    # Decide: win or lose this set?
    for is_win in [True, False]:
        # Try all possible set scores for this set
        possible = generate_valid_set_score(is_win)

        for (pa, pb) in possible:
            if pa + current_set_a <= total_a and pb + sum(p[1] for p in path) <= total_b:
                new_path = path + [(pa, pb)]

                # Prune if remaining points can't fill remaining sets
                rem_sets = total_sets - len(new_path)
                rem_a = total_a - (pa + current_set_a)
                rem_b = total_b - sum(p[1] for p in new_path)

                # Minimum points per set is 0+0, maximum is way higher
                # We can't easily prune by min/max
                if is_win:
                    # Won a set, need to verify final counts
                    if len(new_path) == total_sets:
                        if (pa + current_set_a) == total_a and rem_b == 0:
                            solutions.append((pa, pb))
                            return solutions
                    else:
                        # Keep going recursively
                        recursive_result = find_valid_sets(total_a, total_b, wa, wb, total_sets,
                                                           pa + current_set_a, solutions, new_path)
                        if recursive_result:
                            return solutions

            # Try recursive call
            # If we still need more sets
            if len(new_path) < total_sets:
                result = find_valid_sets(total_a, total_b, wa, wb, total_sets,
                                        pa + current_set_a, solutions, new_path)
                if result is not None:
                    return result

    return None


