                            continue
                        return True
        elif wins_count_needed > 0:
            # Could win
            valid = [make_valid_win()]
            for i, j in valid:
                search(idx + 1, current_a + i, current_b + j, assignments + [(i, j)])

        # Could lose instead
        if losses_count_needed > 0:
            valid = [make_valid_loss()]
            for i, j in valid:
                search(idx + 1, current_a + i, current_b + j, assignments + [(i, j)])
        else:
            return False

    def make_valid_win():
        # Generate reasonable win scores
        results = []
        # Regular: 25-x where x <= 23
        results.append((25, 0))
        results.append((25, 10))
        results.append((25, 20))
        # Deuce: x-y where x=y+2 and x>=26, y>=24
        results.append((26, 24))
        results.append((27, 25))
        results.append((28, 26))
