        results.append((10, 25))
        results.append((20, 25))
        # Deuce
        results.append((24, 26))
        results.append((25, 27))
        return results

    win_options = make_valid_win()
    loss_options = make_valid_loss()

    # Backtrack search
    def backtrack(idx, current_a, current_b, wins_left, losses_left, path):
        if idx == total_sets:
            return current_a == a and current_b == b

        if wins_left > 0:
            for win_a, win_b in win_options:
                new_a = current_a + win_a
                new_b = current_b + win_b
                if new_a <= a and new_b <= b:
                    if backtrack(idx + 1, new_a, new_b, wins_left - 1, losses_left, path + [(win_a, win_b)]):
