                if new_a <= a and new_b <= b:
                    if backtrack(idx + 1, new_a, new_b, wins_left, losses_left - 1, path + [(lose_a, lose_b)]):
                        return path + [(lose_a, lose_b)]

        return False

    if backtrack(0, 0, 0, wa, wb, []):
