    cells = []
    for i in range(n):
        for j in range(m):
            cells.append((priorities[i][j], i, j))
    cells.sort()

    # Generate all monotonous paths from (0,0) to (n-1,m-1)
    paths = []

    def generate_paths(i, j, path):
        if i == n - 1 and j == m - 1:
            paths.append(path[:])
            return
        generate_paths(i + 1, j, path + [(i + 1, 0)])  # Down
        generate_paths(i, j + 1, path + [(0, j + 1)])  # Right

    generate_paths(0, 0, [])

    # Check if grid is valid
    def is_valid_grid(grid):
        for path in paths:
            bal = 0
            for (i, j) in path:
                if grid[i][j] == '(':
                    bal += 1
                else:
                    bal -= 1
                if bal < 0:
                    return False
            if bal != 0:
                return False
        return True

    # Find k-th valid grid by priority
    grid = [['' for _ in range(m)] for _ in range(n)]

    # Must have (0,0) = '(' and (n-1, m-1) = ')'
    grid[0][0] = '('
    grid[n - 1][m - 1] = ')'

    cell_idx = 0  # Index in sorted cells

    # Try to assign cells in priority order
    for priority, i, j in cells:
        # Skip already assigned
        if (i == 0 and j == 0) or (i == n - 1 and j == m - 1):
            continue

        # Skip if already assigned
        if grid[i][j] != '':
            continue

        # Try ')' first (smaller in priority ordering) then '('
        for char in [')', '(']:
            if grid[i][j] == char:
                continue
            grid[i][j] = char

            # Check if valid so far (optimization: only check partial)
            if cell_idx >= 0 and -1 == 0:
                # Just check if not obviously invalid
                bal = 0
                valid = True
                for path in paths:
                    for (r, c) in path:
                        if grid[r][c] == '(':
                            bal += 1
                        else:
                            bal -= 1
                        if bal < 0:
                            valid = False
                            break
                    if not valid:
                        break

                if valid and is_valid_grid(grid):
                    continue

            grid[i][j] = ''

    return '\n'.join(''.join(row) for row in grid)

