def get_divisors(n: int) -> list:
    divs = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i += 1
    return sorted(divs)

def mobius(n: int) -> int:
    if n == 1:
        return 1
    prime_factors = []
    d = 2
    tmp = n
    while d * d <= tmp:
        if tmp % d == 0:
            cnt = 0
            while tmp % d == 0:
                cnt += 1
                tmp //= d
            if cnt > 1:
                return 0
            prime_factors.append(d)
        d += 1
    if tmp > 1:
        prime_factors.append(tmp)
    return -1 if len(prime_factors) % 2 == 1 else 1

