def solution(input_str):
    """
    Solve the problem of counting different decompositions of a number into Fibonacci sum.
    """
    import sys

    def generate_fibonacci_points(target_max):
        """Generate Fibonacci numbers that could be used in decompositions."""
        fibs = [1, 2]
        while fibs[-1] <= target_max:
            fibs.append(fibs[-1] + fibs[-2])
        return fibs

    memo = {}

    def count_decs(target, max_fib_idx):
        """
        Count decompositions using Fibonacci numbers up to max_fib_idx.
        """
        if target == 0:
            return 1
        if target < 0:
            return 0
        if (target, max_fib_idx) in memo:
            return memo[(target, max_fib_idx)]

        result = 0
        fibs = generate_fibonacci_points(10**18)
        limit = max_fib_idx

        # Try all Fibonacci numbers <= min(target, fibs[limit])
        for i in range(min(limit, len(fibs)) - 1, -1, -1):
            if fibs[i] > target:
                continue

            # If we use fibs[i], we can't use fibs[i-1] (would form consecutive)
            result += count_decs(target - fibs[i], i - 2)

        memo[(target, max_fib_idx)] = result
        return result

    # Parse inputs
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        n = int(lines[i])
        fibs = generate_fibonacci_points(n)
        # Count decompositions excluding using n itself
        ans = count_decs(n - 1, len(fibs) - 1) + 1  # +1 for the decomposition using just n
        results.append(str(ans))

    return '\n'.join(results)


