# Final solution using backtracking with memoization
def solution_final(input_str):
    fibs = [1, 2]
    while fibs[-1] <= 10**18:
        fibs.append(fibs[-1] + fibs[-2])

    memo = {}

    def count_decomp(remaining, max_idx):
        if remaining == 0:
            return 1
        if remaining < 0:
            return 0
        if (remaining, max_idx) in memo:
            return memo[(remaining, max_idx)]

        total = 0
        for i in range(max_idx, -2, -1):
            if i < 0:
                break
            fib = fibs[i]
            if fib > remaining:
                continue
            # Can't use consecutive Fibonacci numbers in the same decomposition path
            total += count_decomp(remaining - fib, i - 2)

        memo[(remaining, max_idx)] = total
        return total

    lines = input_str.strip().split('\n')
    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        n = int(lines[i])
