        max_idx = 0
        for j in range(len(fibs)):
            if fibs[j] <= n:
                max_idx = j
            else:
                break

        # The count includes all valid decompositions
        count = count_decomp(n, max_idx)
        results.append(str(count))

    return '\n'.join(results)

from collections import deque

def solution(n_str):
    n = int(n_str.strip())

    if n == 0:
        return "0\n"

    # BFS to find minimum operations
    # dist maps number -> minimum steps to reach it
    dist = {n: 0}
    queue = deque([n])

    while queue:
        curr = queue.popleft()

        if curr == 0:
            return str(dist[0]) + '\n'

        s = str(curr)
        digits = set(int(c) for c in s)

        for d in digits:
            if d > 0:  # Can subtract positive digit
                nxt = curr - d
                if nxt not in dist:
                    dist[nxt] = dist[curr] + 1
                    queue.append(nxt)

    return str(dist[0]) + '\n'

from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 1 or not lines[0].strip():
        return "0"

    n, m = map(int, lines[0].split())

    # Handle edge case with no edges - impossible to have all three weights
    if m == 0:
        return "0"

    # Build adjacency matrix
    adj = [[False] * n for _ in range(n)]
    edge_list = []
    for i in range(1, m + 1):
        if i < len(lines) and lines[i].strip():
            x, y = map(int, lines[i].split())
            x -= 1  # 0-indexed
            y -= 1
            adj[x][y] = adj[y][x] = True
            edge_list.append((x, y))

    # Find connected components
    visited = [False] * n
    components = []
    for i in range(n):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                comp.append(node)
                for neighbor in range(n):
                    if adj[node][neighbor] and not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(comp)

    total = 2 ** n

    def count_independent_sets(comp):
        """Count independent sets in a component (for |not S0| and |not S2|)"""
        k = len(comp)
        if k <= 1:
            return 2

        # Build local adjacency
        adj_l = [[False] * k for _ in range(k)]
        for i in range(k):
            for j in range(i + 1, k):
                if adj[comp[i]][comp[j]]:
                    adj_l[i][j] = adj_l[j][i] = True

        half = k // 2

        # Precompute valid independent sets for left half
        left_valid = [0]
        for mask in range(1, 1 << half):
            valid = True
            for i in range(half):
                if (mask & (1 << i)):
                    for j in range(i + 1, half):
                        if (mask & (1 << j)) and adj_l[i][j]:
                            valid = False
                            break
                    if not valid:
                        break
            if valid:
                left_valid.append(mask)

        # Precompute valid independent sets for right half
        right_valid = [0]
        for mask in range(1, 1 << (k - half)):
            valid = True
            for i in range(k - half):
                if (mask & (1 << i)):
                    for j in range(i + 1, k - half):
                        if (mask & (1 << j)) and adj_l[half + i][half + j]:
                            valid = False
                            break
                    if not valid:
                        break
            if valid:
                right_valid.append(mask)

        # Combine and count
        total_isos = 0
        for lm in left_valid:
            for rm in right_valid:
                ok = True
                for i in range(half):
                    if (lm & (1 << i)):
                        for j in range(k - half):
                            if adj_l[i][half + j]:
                                if (rm & (1 << j)):
                                    ok = False
                                    break
                        if not ok:
                            break
                if ok:
                    total_isos += 1

        return total_isos

    # Calculate |not S0| and |not S2| (same value - independent sets)
    not_S0 = 1
    not_S2 = 1
    for comp in components:
        not_S0 *= count_independent_sets(comp)
        not_S2 *= count_independent_sets(comp)

    # |not S1|: all vertices in each component have same value
    not_S1 = 2 ** len(components)

    # |not S0 ∩ not S1|: edges with 0 AND 1 impossible = all edges have weight 2
    # = vertices incident to edges must be 1, isolated vertices free
    num_isolated = sum(1 for comp in components if len(comp) <= 1)
    not_S0_1 = 2 ** num_isolated

    # |not S1 ∩ not S2|: edges with 1 AND 2 impossible = all edges have weight 0
    # = vertices incident to edges must be 0, isolated vertices free
    not_S1_2 = 2 ** num_isolated

    # |not S0 ∩ not S2|: edges with 0 AND 2 impossible = edges have weight 1 only
    # = graph must be bipartite, 2^num_noniso_components colorings
    not_S0_2 = 1
    num_isolated = sum(1 for comp in components if len(comp) <= 1)
    not_S0_2 *= (2 ** num_isolated)

    for comp in components:
        if len(comp) <= 1:
            not_S0_2 *= 2
            continue

        # Check bipartiteness
        adj_l = [[False] * len(comp) for _ in range(len(comp))]
        for i in range(len(comp)):
            for j in range(i + 1, len(comp)):
                if adj[comp[i]][comp[j]]:
                    adj_l[i][j] = adj_l[j][i] = True

        # BFS for bipartite check
        color = {}
        color[0] = 0
        queue = [0]
        idx = 0
        possible = True
        while idx < len(queue):
            u_local = queue[idx]
            idx += 1
            u = comp[u_local]
            for v in range(len(comp)):
                if adj_l[u_local][v]:
                    v_local = v
                    if v not in color:
                        color[v] = 1 - color[u]
                        queue.append(v_local)
                    elif color[v] == color[u_local]:
                        possible = False
                        break
            if not possible:
                break

        if possible:
            not_S0_2 *= 2

    # Add empty set for independent sets
    not_S0 += 1
    not_S2 += 1

    # Inclusion-exclusion
    ans = total - (not_S0 + not_S1 + not_S2) + (not_S0_1 + not_S1_2 + not_S0_2)

    return str(ans)
